package oepul.o6_1b

import rego.v1

recognised_course(c) if {
	c.provider_recognised
	c.participant_eligible
	c.date >= "2022-01-01"
	c.date <= "2025-12-31"
	c.hours > 0
	c.person_retained_at_deadline
	c.allocated_to_this_farm
}

credited_hours(topic) := sum(hours) if {
	courses := input.documentation.bio_training
	is_array(courses)
	ids := {c.event_id | some c in courses; recognised_course(c)}
	all_ids := [c.event_id | some c in courses; recognised_course(c)]
	count(ids) == count(all_ids)
	hours := [c.hours | some c in courses; recognised_course(c); c.topic == topic]
}

training_met if {
	credited_hours("Biodiversität") >= 3
	credited_hours("Biologische Wirtschaftsweise") >= 5
}

# Der Kooperationspartner und der Kulturbereich sind betriebliche Angaben.
# Die Matrix in Anhang L beantwortet zusätzlich die Frage nach der Einzelfläche.
farm_combination_blocked(m, sector, bio_sector) if {
	m in {"1A", "2", "11", "12"}
	bio_sector == "whole"
	is_string(sector)
}

farm_combination_blocked(m, sector, bio_sector) if {
	m in {"1A", "2", "11", "12"}
	bio_sector in {"arable_grassland", "wine_fruit_hops"}
	sector == bio_sector
}

farm_combination_blocked("1C:NPF", _, bio_sector) if {
	year >= 2025
	bio_sector in {"whole", "arable_grassland"}
}

combination_conflicts contains m.measure if {
	some m in contract.parallel_measures
	farm_combination_blocked(m.measure, m.sector, contract.organic_sector)
}

full_mowing_count(p) := count([d | some d in p.oepul.uses; d.kind == "Mahd"; d.removed])

grass_annual_mowing_met(p) if {
	p.land_use == "grassland"
	some code in p.oepul.codes
	grass_variant(code)
	full_mowing_count(p) >= 1
}

altgrass_carryover_met(p) if {
	p.oepul.previous_altgrass
	p.oepul.control_lost
}

altgrass_carryover_met(p) if {
	p.oepul.previous_altgrass
	"DIVSZ" in p.oepul.codes
	p.oepul.same_location
}

altgrass_last_use_met(p) if {
	"DIVAGF" in p.oepul.codes
	grass_annual_mowing_met(p)
	every u in p.oepul.uses { u.date <= key_date(year, "08-15") }
	p.oepul.overwintered_growth
	p.oepul.prohibited_traffic_or_fertilisation == false
}

cleaning_exempt(p, u) if {
	year >= 2025
	p.oepul.first_claim_new_sowing
	u.kind == "Reinigungsschnitt"
	u.removed == false
}

post_grazing_exempt(u) if {
	u.immediate_after_grazing
	u.removed == false
	u.kind in {"Pflegemahd", "Häckseln"}
}

excused_grazing_care(u) if {
	year >= 2025
	post_grazing_exempt(u)
}

regular_arable_use(p, u) if {
	u.kind in {"Mahd", "Häckseln", "Weide", "Pflegemahd", "Reinigungsschnitt"}
	not cleaning_exempt(p, u)
	not excused_grazing_care(u)
}

problem_relief(p) if {
	some s in p.oepul.invasive_species
	problem_plant(s)
	land.invasive_arable_div_ha * 100 > land.arable_div_ha * 25
	p.oepul.invasive_evidence
}

arable_frequency_limit(p) := 3 if drought_relief(p)

else := 2

arable_frequency_met(p) if {
	p.land_use == "arable"
	"DIV" in p.oepul.codes
	not cross_project(p.oepul.codes)
	is_array(p.oepul.uses)
	every u in p.oepul.uses { valid_arable_kind(u.kind, year) }
	n := count([u | some u in p.oepul.uses; regular_arable_use(p, u)])
	n <= arable_frequency_limit(p)
	n + p.oepul.previous_year_counted_uses >= 1
}

early_arable_grazing_allowed(p) if {
	p.land_use == "arable"
	"DIV" in p.oepul.codes
	drought_relief(p)
}

standard_early_mown_area_ha := land.arable_div_ha * 0.25

arable_removal_allowed(p) if {
	p.oepul.break_date >= first_allowed_break(p.oepul.original_sowing_year, p.oepul.winter_crop_or_cover_follows)
	p.oepul.mechanical_removal
}

arable_fallow_base_ha := min([arable * 0.20, land.eligible_fallow_ha])
wild_brood_bonus_ha := min([20, land.qualified_wild_brood_ha])

wild_brood_sowing_met(p) if {
	p.land_use == "arable"
	"WB" in p.oepul.codes
	p.oepul.double_row_spacing
	p.oepul.row_spacing_cm >= 20
	p.oepul.undersown == false
	p.oepul.cereal_percent >= 50
	p.oepul.crop_sowing_date < key_date(year, "03-15")
	is_string(p.oepul.crop_sowing_date)
}

grass_regional_management_met(p) if {
	p.land_use == "grassland"
	"DIVRS" in p.oepul.codes
	grass_annual_mowing_met(p)
	ordinary := [u | some u in p.oepul.uses; not grass_cleaning(p, u)]
	exported_clean := [u | some u in p.oepul.uses; grass_cleaning(p, u); u.removed]
	count(ordinary) + count(exported_clean) <= 2
	every u in ordinary { u.kind in {"Mahd", "Weide"}; u.date >= key_date(year, "07-15")}
	every u in p.oepul.uses { valid_grass_harvest(u) }
	every t in p.oepul.fertilisers { t in {"Festmist", "Festmistkompost"} }
}

grass_cleaning(p, u) if {
	p.oepul.first_claim_new_sowing
	u.kind == "Reinigungsschnitt"
}

valid_grass_harvest(u) if u.kind in {"Weide", "Reinigungsschnitt"}

valid_grass_harvest(u) if {
	u.kind == "Mahd"
	u.removed
}

arable_fallow_rs_management_met(p) if {
	year >= 2025
	p.land_use == "arable"
	"DIVRS" in p.oepul.codes
	p.oepul.use == "Grünbrache"
	is_array(p.oepul.uses)
	count(p.oepul.uses) <= 1
	count(p.oepul.uses) + p.oepul.previous_year_counted_uses >= 1
	every u in p.oepul.uses { authorised_rs_fallow_operation(p, u) }
}

authorised_rs_fallow_operation(_, u) if {
	u.kind == "Häckseln"
	u.date >= key_date(year, "10-01")
}

authorised_rs_fallow_operation(p, u) if cleaning_exempt(p, u)

arable_forage_rs_management_met(p) if {
	p.land_use == "arable"
	"DIVRS" in p.oepul.codes
	p.oepul.use == "Sonstiges Feldfutter"
	cuts := [u | some u in p.oepul.uses; u.removed]
	count(cuts) in {1, 2}
	every u in p.oepul.uses { forage_rs_use(p, u) }
}

forage_rs_use(_, u) if {
	u.kind == "Mahd"
	u.removed
}

forage_rs_use(p, u) if {
	u.kind == "Reinigungsschnitt"
	p.oepul.first_claim_new_sowing
}

# Für die Acker- und Grünlandquote anrechenbare Projekt- und Sonderflächen.
project_div_credit(p) if {
	p.land_use == "arable"
	"DIV" in p.oepul.codes
	"NAT" in p.oepul.codes
	p.oepul.use == "Grünbrache"
	"SA01" in p.oepul.project_codes
}

project_div_credit(p) if {
	p.land_use == "arable"
	"DIV" in p.oepul.codes
	"EBW" in p.oepul.codes
	p.oepul.use == "Grünbrache"
}

project_div_credit(p) if {
	p.land_use == "grassland"
	"DIVSZ" in p.oepul.codes
	some m in p.oepul.codes
	qualifying_project_code(m, p.oepul.project_codes)
}

project_div_credit(p) if {
	p.land_use == "grassland"
	"DIVSZ" in p.oepul.codes
	"EBW" in p.oepul.codes
	p.oepul.ebw_habitat_and_use_confirmed
	p.oepul.use in {"Einmähdige Wiese", "Mähwiese/-weide zwei Nutzungen"}
}

k20_excluded(p) if {
	p.land_use == "arable"
	"K20" in p.oepul.codes
}

training_deficit[topic] := max([0, hours - credited_hours(topic)]) if {
	some topic, hours in {"Biodiversität": 3, "Biologische Wirtschaftsweise": 5}
}

valid_arable_kind(kind, _) if kind in {"Mahd", "Häckseln", "Pflegemahd", "Reinigungsschnitt"}

valid_arable_kind("Weide", y) if y >= 2025

bio_code_required(p) if {
	contract.organic_sector in {"arable_grassland", "wine_fruit_hops"}
	p.oepul.organic_managed
	p.oepul.crop_sector == contract.organic_sector
}

bio_applicant_status_met if {
	contract.active_farmer
	contract.manages_on_own_account
	contract.public_authority_or_institution == false
}

# Kontrolle der jährlich gemeldeten Abschnitte, mit Zusammenführung mehrerer Begehungen.
indicator_density_met(p) if {
	p.land_use == "grassland"
	p.oepul.use == "Einmähdige Wiese"
}

indicator_density_met(p) if {
	p.land_use == "grassland"
	surveys := [r | some r in p.oepul.species_survey; startswith(r.date, sprintf("%d-", [year])); r.documented]
	sections := {r.strip | some r in surveys}
	count(sections) > 0
	every section in sections {
		names := {n | some r in surveys; r.strip == section; some n in r.indicator_groups}
		kennarten_count(names) >= 5
	}
}

package oepul.o6_1b

import rego.v1

# Die Teilergebnisse beziehen sich jeweils auf eine benannte Anspruchsvoraussetzung.
# Fehlende Beobachtungen ergeben keine positive Entscheidung.
tab := data.bio_tables
year := input.farm.year
land := input.land.oepul
contract := input.farm.oepul
arable := input.land.arable_area_ha
mown := land.mown_grassland_without_mountain_meadows_ha

rate(position, y) := row.eur if {
	y >= 2023
	y <= 2028
	starts := [r.ab | some r in tab.praemiensaetze; r.position == position; r.ab <= y]
	some row in tab.praemiensaetze
	row.position == position
	row.ab == max(starts)
}

contract_years := row.jahre if {
	some row in tab.vertragsjahre
	row.beginn == contract.first_bio_year
}

ordinary_entry_timely if {
	contract_years > 0
	is_string(contract.application_date)
	contract.application_date <= sprintf("%d-12-31", [contract.first_bio_year - 1])
}

minimum_size_met if contract.first_oepul_year < year

minimum_size_met if {
	contract.first_oepul_year == year
	land.protected_cultivation_at_ha >= 0.5
}

minimum_size_met if {
	contract.first_oepul_year == year
	land.minimum_size_basis_at_ha >= 1.5
}

control_contract_met if {
	contract.registered_food_authority
	contract.recognised_control_body
	is_string(contract.control_start)
	contract.control_start <= sprintf("%d-01-01", [contract.first_bio_year])
	contract.control_continuous_through >= sprintf("%d-12-31", [year])
	year >= contract.first_bio_year
	year <= 2028
}

partial_separation_met if {
	contract.organic_sector in {"arable_grassland", "wine_fruit_hops"}
	contract.separate_facilities_and_land
	contract.separate_crop_sectors
	contract.separate_input_storage
}

household_exception_met if {
	c := input.livestock.oepul
	c.household_pigs <= 2
	c.household_hens <= 10
	c.other_nonorganic_household_animals == 0
	c.separate_household_feed
}

mixed_equids if {
	input.livestock.oepul.organic_equids > 0
	input.livestock.oepul.conventional_equids > 0
}

rgve_factor(category) := r.faktor if {
	some r in tab.viehschluessel
	r.kategorie == category
	r.einheit == "RGVE"
}

stock_contribution(g) := 0 if g.qualifies_for_bio_rgve == false

else := n if {
	g.qualifies_for_bio_rgve
	is_number(g.annual_assessable_count)
	g.annual_assessable_count >= 0
	n := g.annual_assessable_count * rgve_factor(g.category)
}

stock_density := sum(amounts) / forage if {
	groups := input.livestock.species_groups
	amounts := [stock_contribution(g) | some g in groups]
	count(amounts) == count(groups)
	forage := input.land.grassland_area_ha + land.arable_forage_ha
	forage > 0
}

stock_class := "ohne" if stock_density < 0.30

else := "mittel" if stock_density < 1.40

else := "hoch" if stock_density >= 1.40

grass_base_rate := rate(sprintf("gruen_basis_%s", [stock_class]), year)

grassland_conversion_excess := max([0, (land.chargeable_grassland_conversion_ha - land.eligible_grassland_creation_ha) - 1])

psm_declaration_code(kind, y) := r.code if {
	y >= 2023
	y <= 2025
	some r in tab.psm_codes
	r.mittel == kind
}

required_div(area) := area * 0.07 if area > 2

else := 0 if area >= 0

arable_div_required_ha := required_div(arable)
grass_div_required_ha := required_div(mown)

grass_credit_ha := 0 if arable > 10

else := 0 if land.additional_qualifying_grass_div_ha == 0

else := min([land.additional_qualifying_grass_div_ha, max([0, land.grass_div_ha - grass_div_required_ha])]) if arable < 10

# Bei genau 10 ha widersprechen sich SRL und Informationsblatt. Unstrittige
# Fälle mit ausreichender Ackerfläche bleiben entscheidbar.
arable_div_met if land.arable_div_ha >= arable_div_required_ha
arable_div_met if land.arable_div_ha + grass_credit_ha >= arable_div_required_ha
grass_div_met if land.grass_div_ha >= grass_div_required_ha

required_field_div(total, field) := 0.15 if {
	total >= 10
	field > 5
}

else := 0 if {
	total >= 0
	field >= 0
}

field_shortfall[f.id] := max([0, (((required_field_div(arable, f.basis_ha) * 10000) - (f.div_ha * 10000)) - (f.gloez_lse_ha * 10000)) - (af * 10000)]) / 10000 if {
	some f in land.fields
	f.use == "arable"
	af := agroforestry_credit(f, year)
}

field_shortfall[f.id] := max([0, ((required_field_div(mown, f.basis_ha) * 10000) - (f.div_ha * 10000)) - (f.gloez_lse_ha * 10000)]) / 10000 if {
	some f in land.fields
	f.use == "grassland"
}

agroforestry_credit(f, y) := f.assigned_1c_strip_ha if y >= 2025

else := 0 if y < 2025

div_bonus_area(basis, pure) := max([0, min([pure, basis * 0.20]) - (basis * 0.07)])
arable_extra_div_ha := div_bonus_area(arable, land.pure_arable_div_ha)
grass_extra_div_ha := div_bonus_area(mown, land.pure_grass_div_ha)

density_bonus(basis, areas) if {
	basis > 0
	count([a | some a in areas; a > 0.05]) >= ceil(basis / 3)
}

arable_density_bonus_ha := min([arable * 0.20, land.pure_arable_div_ha]) if density_bonus(arable, land.arable_div_plot_sizes_ha)
grass_density_bonus_ha := min([mown * 0.20, land.pure_grass_div_ha]) if density_bonus(mown, land.grass_div_plot_sizes_ha)

crop_exempt(name, _) if name in tab.ackerfutter

crop_exempt(name, y) if {
	y >= 2025
	name in {"Grünbrache", "Spargel"}
}

excess_cereal_maize_ha := max([0, land.cereal_and_maize_ha - (arable * 0.75)]) if arable > 5

single_crop_excess[c.botanical_species] := c.area_ha - (arable * 0.55) if {
	arable > 5
	some c in land.main_crops
	is_string(c.use)
	not crop_exempt(c.use, year)
	c.area_ha > arable * 0.55
}

forage_crop(c) if c in tab.ackerfutter
cereal(c) if c in tab.getreide
vegetable_or_strawberry(c) if c in tab.feldgemuese
vegetable_or_strawberry(c) if c == "Erdbeeren"

vegetable_or_strawberry(c) if {
	some group in tab.feldgemuese
	c in split(group, "/")
}

special_use_excluded(c) if c in tab.spezialausnahmen

fruit(c, y) if {
	some r in tab.obst
	c in object.get(r, "bezeichnungen", [r.name])
	r.ab <= y
}

crop_position(c) := r.position if {
	some r in tab.kulturgruppen
	r.kultur == c
}

else := "bhg" if c in tab.bhg

circular_crop(c) if {
	some r in tab.kulturgruppen
	r.kultur == c
	r.kreislauf
}

arable_circular_rate := rate(position, year) if {
	year >= 2025
	stock_density < 1.40
	position := {"ohne": "kreislauf_acker_ohne", "mittel": "kreislauf_acker_mit"}[stock_class]
	land.circular_arable_ha * 100 > arable * 15
	arable > 0
}

grass_circular_rate := rate("kreislauf_gruen", year) if {
	stock_class == "mittel"
	mown > 0
	land.div_or_species_rich_grass_ha > mown * 0.08
}

max_crop_rate(p) := max([rate(pos, year) | some pos in p.eligible_crop_positions])
eligible_crop_area := sum([p.area_ha | some p in input.land.parcels; p.land_use == "arable"; max_crop_rate(p) > 0])
high_rate_area(v) := sum([p.area_ha | some p in input.land.parcels; p.land_use == "arable"; max_crop_rate(p) > v])

# Je Schlag zählt nur die höher dotierte Erst-/Zweitkultur. Bei gleicher
# Prämienstufe wird erst die gesamte Stufenfläche zusammengefasst.
crop_bonus_eur := sum(amounts) if {
	is_array(input.land.parcels)
	every p in input.land.parcels { crop_record_complete(p) }
	eligible_crop_area + max([0, land.arable_div_ha - (arable * 0.07)]) > arable * 0.15
	rates := {max_crop_rate(p) | some p in input.land.parcels; p.land_use == "arable"}
	amounts := [amount |
		some v in rates
		ha := sum([p.area_ha | some p in input.land.parcels; p.land_use == "arable"; max_crop_rate(p) == v])
		amount := v * min([ha, max([0, (arable * 0.40) - high_rate_area(v)])])
	]
}

bee_premium_eur := 0 if input.livestock.oepul.sector_programme_feed_or_wax

else := first + rest if {
	input.livestock.oepul.sector_programme_feed_or_wax == false
	n := input.livestock.oepul.claimed_eligible_colonies
	n >= 0
	first := min([100, n]) * rate("volk_1", year)
	rest := max([0, min([900, n]) - 100]) * rate("volk_2", year)
}

eligible_colony(h) if {
	h.controlled_organic
	h.combs_at_cherry_blossom >= 6
	h.brood_combs
	h.laying_queen
	h.economic_colony
}

tier_area(t, ha) := max([0, ha - t.von]) if t.bis == null

else := max([0, min([ha, t.bis]) - t.von])

modulation(ha) := sum([part | some t in tab.modulation; part := tier_area(t, ha) * t.faktor]) / ha if ha > 0
modulation_factor := modulation(land.home_modulation_area_ha)
loss_tolerance_ha := max([0.50, min([5, 0.05 * land.prior_committed_ha])])
repay_area_ha := land.chargeable_loss_ha if land.chargeable_loss_ha > loss_tolerance_ha

else := 0 if land.chargeable_loss_ha <= loss_tolerance_ha

new_area_payable_ha := land.new_uncommitted_ha if year in {2024, 2025}

else := min([land.new_uncommitted_ha, max([0, max([5, land.bio_2025_ha * 0.50]) - land.additions_already_counted_ha])]) if {
	year >= 2026
	year <= 2028
}

parcel_cap(group, y) := r if {
	some r in tab.obergrenzen
	r.bereich == group
	y >= r.ab
	y <= r.bis
}

combination(left, right) := r.zelle if {
	some r in tab.kombinationen
	r.von == left
	r.mit == right
}

project_combination(left, right) := r.zelle if {
	some r in tab.projektkombinationen
	r.von == left
	r.mit == right
}

allowed_switch(from, to, y) if {
	some r in tab.wechsel
	r.von == from
	r.nach == to
	y <= r.bis_jahr
	y >= 2023
}

crop_record_complete(p) if p.land_use != "arable"

crop_record_complete(p) if {
	p.land_use == "arable"
	is_number(p.area_ha)
	is_array(p.eligible_crop_positions)
	every pos in p.eligible_crop_positions { pos in {"feldfutter", "leguminosen", "kreuzbluetler", "sonnenblume", "bhg"} }
}

package oepul.o6_1b

import rego.v1

# Datumsangaben im Profil sind ISO-Kalendertage ohne Uhrzeit.
day(date) := time.parse_rfc3339_ns(concat("", [date, "T00:00:00Z"])) / 86400000000000
key_date(y, month_day) := sprintf("%04d-%s", [y, month_day])

standard_mix_met(m) if {
	m.insect_pollinated_species >= 7
	m.insect_pollinated_families >= 3
	m.non_insect_stand_percent <= 10
}

seed_rows("arable") := tab.arten_acker
seed_rows("grassland") := tab.arten_gruenland

seed_taxon(use, name) := r if {
	some r in seed_rows(use)
	name in {r.wissenschaftlich, r.deutsch}
}

seed_taxon("grassland", "Plantago lanceolata") := r if {
	some r in tab.arten_gruenland
	r.deutsch == "Spitz-Wegerich"
}

regional_partner_ok(use, s) if {
	s.regional_origin_verified
	s.certified_ecotype == false
	s.weight_percent > 0
	s.weight_percent <= 5
	seed_taxon(use, s.species)
}

regional_partner_ok(_, s) if {
	s.regional_origin_verified
	s.certified_ecotype
	s.weight_percent > 0
}

regional_mix_met(use, m) if {
	m.kg_per_ha >= 20
	m.labels_and_invoices
	every s in m.components { regional_partner_ok(use, s) }
	species := {r.wissenschaftlich | some s in m.components; r := seed_taxon(use, s.species)}
	families := {r.familie | some s in m.components; r := seed_taxon(use, s.species)}
	every taxon in species {
		ordinary := [s.weight_percent | some s in m.components; s.certified_ecotype == false; seed_taxon(use, s.species).wissenschaftlich == taxon]
		sum(ordinary) <= 5
	}
	count(species) >= 30
	count(families) >= 7
	sum([s.weight_percent | some s in m.components]) == 100
}

regional_grass_site(p) if {
	is_number(p.slope_percent)
	p.slope_percent < 18
	p.oepul.soil_rating >= 30
}

old_div_code(code) if code in tab.altcodes
problem_plant(name) if name in tab.problemarten

qualifying_project_code(measure, codes) if {
	some row in tab.schnittauflagen
	row.massnahme == measure
	row.code in codes
}

slk_tier(variety, y) := r.stufe if {
	some r in tab.seltene_sorten
	r.sorte == variety
	r.ab <= y
}

slk_amount(variety, ha, y) := min([10, ha]) * rate(position, y) if {
	ha >= 0
	position := concat("", ["slk_", lower(slk_tier(variety, y))])
}

first_allowed_break(sowing_year, winter_or_cover) := key_date(sowing_year + 1, "08-01") if winter_or_cover == true

else := key_date(sowing_year + 1, "09-15") if winter_or_cover == false

cross_project(codes) if {
	some c in codes
	c in {"NAT", "EBW", "N2"}
}

drought_relief(p) if {
	year == 2026
	"OPBIO" in p.oepul.codes
	p.oepul.other_use_restrictions == false
	not cross_project(p.oepul.codes)
}

rest_days(p) := 49 if drought_relief(p)

else := 63

nfz_second_use_met(p) if {
	"DIVNFZ" in p.oepul.codes
	day(p.oepul.second_use) - day(p.oepul.first_use_completed) > rest_days(p)
}

# Vorgezogene DIVSZ-Nutzung unter OPBIO erfordert auch den Vergleichsschnitt.
early_sz_met(p) if {
	"DIVSZ" in p.oepul.codes
	drought_relief(p)
	shift := p.oepul.phenology_days
	shift >= 4
	shift <= 7
	is_string(p.oepul.comparable_second_cut)
	p.oepul.comparable_second_cut <= p.oepul.first_use
	day(p.oepul.first_use) >= (day(key_date(year, "06-15")) - shift) - 14
}

regular_sz_met(p) if {
	"DIVSZ" in p.oepul.codes
	shift := p.oepul.phenology_days
	shift >= 0
	shift <= 10
	first := day(p.oepul.first_use)
	first >= day(key_date(year, "06-15")) - shift
	sz_release(p, first, shift)
}

sz_release(p, _, _) if p.oepul.single_cut_meadow

sz_release(p, _, _) if {
	is_string(p.oepul.comparable_second_cut)
	p.oepul.comparable_second_cut <= p.oepul.first_use
}

sz_release(_, first, shift) if first >= day(key_date(year, "07-15")) - shift

variant_change(old, new, date, y) if {
	old == "DIVSZ"
	new in {"DIVNFZ", "DIVAGF"}
	date > key_date(y, "04-15")
	date <= key_date(y, "06-15")
}

variant_change(old, new, date, y) if {
	old == "DIVNFZ"
	new == "DIVAGF"
	date > key_date(y, "04-15")
	date <= key_date(y, "08-15")
}

arable_drought_third_use(p) if {
	p.land_use == "arable"
	"DIV" in p.oepul.codes
	drought_relief(p)
	p.oepul.counted_uses == 3
}

drought_region(state, district) if {
	some r in tab.duerre_bezirke
	r.land == state
	r.bezirk in {null, district}
}

harvest_waiver(p) if {
	year == 2026
	p.land_use == "arable"
	p.oepul.drought_destroyed_harvest
	p.oepul.heat_sensitive_late_crop
	drought_region(p.oepul.federal_state, p.oepul.district)
}

erosion_risk(p) if {
	p.land_use == "arable"
	p.area_ha > 0.5
	p.oepul.predominant_slope_percent >= 10
	p.crop.crop_name in tab.erosionskulturen
}

erosion_full(p) if {
	p.oepul.measure8
	p.oepul.erosion_procedure in {"Mulchsaat", "Direktsaat", "Strip-Till"}
	p.oepul.measure6_or_7
}

erosion_full(p) if {
	p.oepul.measure8
	p.oepul.erosion_procedure == "Anhäufungen bei Kartoffeln"
	p.crop.crop_name == "Kartoffeln"
}

erosion_full(p) if {
	p.oepul.measure8
	p.oepul.erosion_procedure == "Untersaat"
	undersowing_crop(p.crop.crop_name, year)
}

undersowing_crop(c, _) if c in {"Ackerbohnen", "Kürbisse", "Sojabohnen", "Sonnenblumen"}

undersowing_crop(c, y) if {
	y >= 2025
	c in {"Mais", "Sorghum"}
}

erosion_base_factor(p) := 1 if {
	erosion_risk(p)
	erosion_full(p)
}

else := 0.5 if {
	erosion_risk(p)
	is_boolean(p.oepul.measure8)
	is_boolean(p.oepul.measure6_or_7)
	is_string(p.oepul.erosion_procedure)
	year >= 2025
}

else := 0 if {
	erosion_risk(p)
	is_boolean(p.oepul.measure8)
	is_boolean(p.oepul.measure6_or_7)
	is_string(p.oepul.erosion_procedure)
	year <= 2024
}

trap_operation_met(p) if {
	year >= 2025
	"PZR" in p.oepul.codes
	p.oepul.sugar_beet_current_or_previous_harvest
	t := p.oepul.traps
	count(t.empty_dates) >= 2
	t.number >= 15 * p.area_ha
	t.annual_lures_installed
	t.catch_containers
	start := day(t.installed)
	start - day(t.sowing_or_comparable_date) <= 14
	start >= day(t.sowing_or_comparable_date)
	day(t.removed) - start >= 35
	t.removed < t.harvest
	count({d | some d in t.empty_dates; day(d) >= start; day(d) <= start + 35; d <= t.removed}) >= 2
}

lse_geometry(e) if {
	e.distance_to_farmed_land_m <= 5
	e.crown_diameter_m >= 2
	e.area_m2 <= 100
	e.nearest_lse_m >= 5
	e.under_control_all_year
	e.claimed
	e.gloez == false
	e.on_alp_or_rough_pasture == false
}

orchard_tree(e, y) if {
	lse_geometry(e)
	e.strong_large_crowned_high_or_half_standard
	e.shared_permanent_support == false
	some r in tab.streuobst
	r.name == e.species
	r.ab <= y
	e.wild_form in {false, r.wildform}
}

hedge_met(h, y) if {
	h.planted >= "2023-01-01"
	h.planted <= key_date(y, "05-15")
	h.adjacent_own_arable_field
	h.long_side_wood_or_lse == false
	h.average_width_m >= 5
	h.average_width_m <= 20
	h.permanent_herb_percent >= 20
	h.mainly_shrubs_fruit_trees
	h.woody_plants_maintained
	h.herb_harvest_or_grazing == false
	h.fertiliser_or_disallowed_psm == false
	h.land_concept
	h.gis_confirmed
}

eligible_steep(p) if {
	p.land_use == "grassland"
	p.slope_percent >= 50
	count(p.operations.cutting_dates) >= 1
	p.oepul.use in {"Einmähdige Wiese", "Streuwiese", "Mähwiese/-weide zwei Nutzungen", "Mähwiese/-weide drei und mehr Nutzungen"}
}

soil_bonus_rate(p) := rate("acker_bonitaet", year) if {
	p.land_use == "arable"
	p.oepul.qualifies_for_bio_div_premium
	p.oepul.soil_rating >= 50
}

else := rate("gruen_bonitaet", year) if {
	p.land_use == "grassland"
	p.oepul.qualifies_for_bio_div_premium
	p.oepul.soil_rating >= 30
}

parcel_premium_blocked(p) if {
	some c in p.oepul.codes
	c in {"OP", "OPBIO", "VF"}
}

parcel_premium_blocked(p) if special_use_excluded(p.oepul.use)
parcel_premium_blocked(p) if p.oepul.use in {"Sonstige Spezialkulturflächen", "Sonstige Weinflächen", "Sonstige Ackerflächen", "Sonstige Grünlandflächen", "Sonstige Hutweideflächen", "Sonstige Flächen im geschützten Anbau"}
parcel_premium_blocked(p) if p.oepul.national_park in {"Neusiedlersee", "Donau-Auen"}
parcel_premium_blocked(p) if p.oepul.relevant_national_park_obligations
parcel_premium_blocked(p) if p.oepul.country != "AT"

eligible_monitoring_program(program, _, _) if {
	some r in tab.monitoring
	r.position == program
	count(r.nat_codes) == 0
}

eligible_monitoring_program(program, codes, nat) if {
	nat == true
	some r in tab.monitoring
	r.position == program
	some c in r.nat_codes
	c in codes
}

kennarten_count(names) := count({r.deutsch | some r in tab.kennarten; some n in names; n in r.bezeichnungen})

grass_variant(code) := r if {
	some r in tab.varianten
	r.code == code
}

dwarf_breed(name) if name in tab.zwergrinder
sanction_options(y) := [r | some r in tab.sanktionsstufen; r.ab <= y; y <= r.bis]

# Teilergebnisse pro Schlag sind auch ohne vollständige betriebliche Abrechnung abfragbar.
parcel_findings contains {"parcel_id": p.parcel_id, "result": "BIO-Flächenprämie ausgeschlossen"} if {
	some p in input.land.parcels
	parcel_premium_blocked(p)
}

parcel_findings contains {"parcel_id": p.parcel_id, "result": "Ernteausnahme 2026 ohne Einzelmeldung"} if {
	some p in input.land.parcels
	harvest_waiver(p)
}

parcel_findings contains {"parcel_id": p.parcel_id, "result": "Dritte Nutzung unter OPBIO"} if {
	some p in input.land.parcels
	arable_drought_third_use(p)
}

parcel_findings contains {"parcel_id": p.parcel_id, "result": "DIVNFZ-Ruhefrist erfüllt"} if {
	some p in input.land.parcels
	nfz_second_use_met(p)
}

parcel_findings contains {"parcel_id": p.parcel_id, "result": "DIVSZ-Nutzungstermin zulässig"} if {
	some p in input.land.parcels
	regular_sz_met(p)
}

parcel_findings contains {"parcel_id": p.parcel_id, "result": "DIVSZ-Frühnutzung mit OPBIO"} if {
	some p in input.land.parcels
	early_sz_met(p)
}

package oepul.o6_1b

import rego.v1

# Die KG-Prüfung ist der räumlichen Prüfung der einzelnen Parzelle vorgelagert.
listed_kg("BAW", kg) if {
	some r in tab.baw_katastralgemeinden
	r.kg_nummer == kg
}

listed_kg("AG", kg) if {
	some r in tab.gwa_katastralgemeinden
	r.kg_nummer == kg
}

listed_baw_site(p) if {
	listed_kg("BAW", p.oepul.kg_nummer)
	p.oepul.baw_gis_confirmed
}

listed_ag_site(p) if {
	listed_kg("AG", p.oepul.kg_nummer)
	p.oepul.annual_groundwater_zone_confirmed
	p.oepul.soil_rating <= 40
}

nat_phenology(code) := r if {
	some r in tab.nat_phaenologie
	r.code == code
}

nat_fallow_care(code) := r if {
	some r in tab.nat_stilllegung_pflege
	r.code == code
}

n2_project_rate(code, y) := r.eur_ha if {
	some r in tab.natura_teilpraemien
	r.code == code
	y >= r.ab
}

slk_all_origins(group, y) := r.stufe if {
	some r in tab.seltene_sorten
	group in r.alle_herkuenfte_von
	y >= r.ab
}

undersowing_timing_met(p) if {
	undersowing_crop(p.crop.crop_name, year)
	p.oepul.undersowing_species_count >= 3
	elapsed := day(p.oepul.undersowing_date) - day(p.oepul.crop_sowing_date)
	elapsed >= 0
	elapsed <= 56
	p.oepul.undersowing_date <= key_date(year, "06-30")
}

# Nur der Teilanspruch auf die beschäftigungs- und größenunabhängige Pauschale.
transaction_cost_eur := rate("transaktion", year) if {
	contract.approved_bio_participation
}

arable_harvest_standard_met(p) if {
	p.land_use == "arable"
	is_string(p.oepul.use)
	not forage_crop(p.oepul.use)
	p.oepul.specific_minimum_management_exemption == false
	p.oepul.crop_properly_established
	p.oepul.annual_care_complete
	p.area_ha > 0
	p.oepul.harvested_and_removed_ha * 100 >= 85 * p.area_ha
}

arable_harvest_standard_met(p) if {
	harvest_waiver(p)
	p.oepul.crop_properly_established
	p.oepul.annual_care_complete
}

credit_special_arable_div(p) if {
	p.land_use == "arable"
	"DIV" in p.oepul.codes
	some c in p.oepul.codes
	c in {"BAW", "AG"}
	p.oepul.use in {"Grünbrache", "Sonstiges Feldfutter"}
	p.oepul.arable_div_care_met
}

credit_special_arable_div(p) if {
	"DIV" in p.oepul.codes
	p.oepul.use == "LSE Mehrnutzenhecke"
	p.oepul.herb_strip_care_met
}

credit_special_arable_div(p) if {
	p.land_use == "arable"
	"DIV" in p.oepul.codes
	some c in p.oepul.codes
	eligible_gloez(c, year)
	p.oepul.all_arable_div_management_met
}

eligible_gloez("GLÖZ 4", _) := true

eligible_gloez("GLÖZ 8", y) if y <= 2024

parcel_findings contains {"parcel_id": p.parcel_id, "result": "Erntekriterium Acker erfüllt"} if {
	some p in input.land.parcels
	arable_harvest_standard_met(p)
}

parcel_findings contains {"parcel_id": p.parcel_id, "result": "Zusätzliche Ackerfläche mit DIV anrechenbar"} if {
	some p in input.land.parcels
	credit_special_arable_div(p)
}

# Jeder begünstigte Schlag zählt einmal. Der Deckel bezieht sich auf die Kulturfläche.
soil_bonus_area(use, basis_ha) := min([basis_ha * 0.20, sum(eligible)]) if {
	basis_ha >= 0
	is_array(input.land.parcels)
	every p in input.land.parcels {
		soil_record_complete(p, use)
	}
	eligible := [p.area_ha | some p in input.land.parcels; p.land_use == use; soil_bonus_rate(p) > 0]
}

soil_record_complete(p, use) if p.land_use != use

soil_record_complete(p, _) if p.oepul.qualifies_for_bio_div_premium == false

soil_record_complete(p, _) if {
	p.oepul.qualifies_for_bio_div_premium
	is_number(p.oepul.soil_rating)
	is_number(p.area_ha)
}

lse_field_maximum(field_area_ha) := floor(field_area_ha * 80) if field_area_ha >= 0

monitoring_entry_timely(application, first_year) if {
	first_year >= 2023
	first_year <= 2028
	day(application) <= day(key_date(first_year - 1, "12-31"))
}

two_year_site_binding_met(p) if {
	p.oepul.control_lost
}

two_year_site_binding_met(p) if {
	p.oepul.converted_to_grassland
}

two_year_site_binding_met(p) if {
	p.oepul.same_location
	p.oepul.successive_div_claim_years >= 2
}

